  function normaliseLocale(value){
    const raw=String(value||'').replace('_','-').trim();
    const aliases={'pt':'pt-PT','pt-pt':'pt-PT','en':'en-GB','en-gb':'en-GB','en-us':'en-GB','es':'es-ES','es-es':'es-ES','fr':'fr-FR','fr-fr':'fr-FR','zh':'zh-CN','zh-cn':'zh-CN','zh-hans':'zh-CN','zh-hans-cn':'zh-CN'};
    return aliases[raw.toLowerCase()]||raw;
  }
  function enabledCodes(){return (Array.isArray(config.enabledLocales)?config.enabledLocales:[]).map(x=>normaliseLocale(x&&x.code)).filter(Boolean);}
  function isEnabled(code){const list=enabledCodes();return !list.length||list.includes(code);}
  function currentClientId(){return parseInt(config.clientId||0,10)||0;}
  function portalRoot(){
    try{
      const nodes=Array.from(document.querySelectorAll('#routespro-client-portal, #routespro-app, [data-fieldflow-locale-host="1"], [data-fieldflow-portal]'));
      if(!nodes.length)return null;
      const active=nodes.find(el=>{const id=parseInt(el.getAttribute('data-client-id')||0,10)||0;return id>0&&(!el.hasAttribute('hidden'));});
      return active||nodes[0];
    }catch(_e){return null;}
  }
  function portalClientId(){
    try{
      const portal=portalRoot();
      if(!portal)return 0;
      const picker=portal.querySelector&&portal.querySelector('#rpcp-client,[data-fieldflow-client-picker]');
      const picked=parseInt((picker&&picker.value)||0,10)||0;
      if(picked>0)return picked;
      return parseInt((portal.getAttribute&&portal.getAttribute('data-client-id'))||0,10)||0;
    }catch(_e){return 0;}
  }
  function dispatchContextChanged(reason){
    try{window.dispatchEvent(new CustomEvent('fieldflow:i18n-context-changed',{detail:{clientId:currentClientId(),locale,allowUserSwitch:!!config.allowUserSwitch,enabledLocales:enabledCodes(),reason:reason||'context',contract:LOCALE_BRAND_SCOPE_CONTRACT,appShellContract:APP_SHELL_LOCALE_CONTRACT,autoTranslationContract:AUTO_TRANSLATION_CONTRACT,adaptiveDockContract:ADAPTIVE_LOCALE_DOCK_CONTRACT}}));}catch(_e){}
  }
  // Historical 9CB certification marker: '--ff-lang-primary':'--ff-primary'. Runtime now also supports --rp-primary-solid fallback.
  function applyLegacyBrand(target){
    if(!target||!target.style||typeof window.getComputedStyle!=='function')return;
    try{
      const portal=portalRoot();if(!portal)return;
      const computed=window.getComputedStyle(portal);
      const read=(a,b)=>String(computed.getPropertyValue(a)||computed.getPropertyValue(b)||'').trim();
      const pairs={
        '--ff-lang-primary':['--ff-primary','--rp-primary-solid'],'--ff-lang-accent':['--ff-accent','--rp-accent-solid'],'--ff-lang-surface':['--ff-surface','--rp-surface'],
        '--ff-lang-text':['--ff-text','--rp-text'],'--ff-lang-muted':['--ff-muted','--rp-muted'],'--ff-lang-border':['--ff-border','--rp-border'],
        '--ff-lang-button-text':['--ff-button-text','--rp-button-text'],'--ff-lang-button-hover-text':['--ff-button-hover-text','--rp-button-hover-text'],'--ff-lang-link-hover':['--ff-link-hover','--rp-link-hover']
      };
      Object.keys(pairs).forEach(key=>{const value=read(pairs[key][0],pairs[key][1]);if(value)target.style.setProperty(key,value);});
    }catch(_e){}
  }
  function hasLiveReactSwitcher(){try{return !!document.querySelector('#fieldflow-react-locale-switcher-root .ff-language-switcher-react');}catch(_e){return false;}}
